$ErrorActionPreference='Stop';$root='release/compliance-platform/v1.6.0-rc1';if(!(Test-Path $root)){throw 'RC package directory missing.'};$rootFull=(Resolve-Path $root).Path.TrimEnd('\');$manifest=Join-Path $rootFull 'manifest.sha256';Get-ChildItem $rootFull -Recurse -File|Where-Object{$_.FullName-ne$manifest}|Sort-Object FullName|ForEach-Object{$hash=Get-FileHash $_.FullName -Algorithm SHA256;$relative=$_.FullName.Substring($rootFull.Length+1).Replace('\','/');"$($hash.Hash.ToLowerInvariant())  $relative"}|Set-Content $manifest;Write-Host 'Compliance RC SHA-256 manifest GENERATED'